import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"compile-js target","description":"","frontmatter":{"title":"`compile-js` target","type":"adr","date":"2026-10-28T00:00:00.000Z","status":"accepted","status_note":"Accepted — extracted in ADR-0128 Phase 5."},"headers":[],"relativePath":"web/project/adrs/0143-compile-js-target.md","filePath":"vendored/web/project/adrs/0143-compile-js-target.md"}'),a={name:`web/project/adrs/0143-compile-js-target.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0143-compile-js-target" tabindex="-1">ADR-0143: <code>compile-js</code> target <a class="header-anchor" href="#adr-0143-compile-js-target" aria-label="Permalink to “ADR-0143: compile-js target”">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p><a href="./../0114-handl-compile-plugin-architecture.html">ADR-0114</a> states the compile port (<code>Compiler</code> / <code>CompilerRegistry</code>); <code>plugin-ext-compile</code>&#39;s dispatcher statically registers every compiler, and <code>host-cli</code> statically depends on <code>plugin-compile-js</code>. JS emission is a web concern.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p><code>web</code> owns the JS compiler: <code>plugin-compile-js</code> (target <code>js</code>), including its lowering (and the <code>proof.rs</code> <code>Path</code>/<code>Equiv</code> lowerers — currently implemented but never dispatched), together with the JS/<code>.hfc</code>/view surfaces of <a href="./../0116-handl-sfc-format.html">ADR-0116</a> and <a href="./../0117-handl-view-component-syntax.html">ADR-0117</a>.</p><p><code>host</code> keeps the port and the registry seam; a host opts the target in via a feature on its own manifest.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><code>host-cli</code>&#39;s dependency on <code>plugin-compile-js</code> becomes an explicit git dep in <code>cli/</code> — the <code>hnl</code> binary&#39;s target set <em>is</em> its dep list.</li><li>The static <code>registry.register(Box::new(JsCompiler))</code> in the platform dispatcher is deleted; the target is registered from this module.</li><li>A JS-specific change no longer rebuilds the platform workspace.</li></ul>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};